export function horizontalStep(camera,x,y,seconds,speed=.45){let fx=-camera[8],fz=-camera[10],n=Math.hypot(fx,fz);if(n<.15){let rx=camera[0],rz=camera[2],r=Math.hypot(rx,rz);if(r<.15){rx=1;rz=0;r=1;}fx=rz/r;fz=-rx/r;n=1;}fx/=n;fz/=n;const magnitude=Math.max(1,Math.hypot(x,y)),dt=Math.max(0,Math.min(.05,seconds));return [((-fz)*x+fx*(-y))/magnitude*dt*speed,(fx*x+fz*(-y))/magnitude*dt*speed];}
export class Joystick {
 constructor(node){this.node=node;this.x=this.y=0;this.pointer=null;const update=e=>{const r=node.getBoundingClientRect(),dx=(e.clientX-r.left-r.width/2)/(r.width*.38),dy=(e.clientY-r.top-r.height/2)/(r.height*.38),d=Math.max(1,Math.hypot(dx,dy));this.x=dx/d;this.y=dy/d;node.querySelector('span').style.transform='translate('+this.x*28+'px,'+this.y*28+'px)';};node.onpointerdown=e=>{if(this.pointer!==null)return;e.preventDefault();e.stopPropagation();this.pointer=e.pointerId;node.setPointerCapture(e.pointerId);update(e);};node.onpointermove=e=>{if(e.pointerId!==this.pointer)return;e.preventDefault();e.stopPropagation();update(e);};for(const event of ['pointerup','pointercancel','lostpointercapture'])node.addEventListener(event,e=>{if(e.pointerId===this.pointer){e.preventDefault();e.stopPropagation();this.stop();}});node.addEventListener('beforexrselect',e=>e.preventDefault());window.addEventListener('blur',()=>this.stop());document.addEventListener('visibilitychange',()=>this.stop());}
 stop(){const id=this.pointer;this.pointer=null;this.x=this.y=0;this.node.querySelector('span').style.transform='translate(0,0)';if(id!==null&&this.node.hasPointerCapture(id))try{this.node.releasePointerCapture(id);}catch{}}
}

export function elevationYawStep(x,y,seconds){const dt=Math.max(0,Math.min(.05,seconds)),n=Math.max(1,Math.hypot(x,y));return {dy:-y/n*dt*.35,yaw:-x/n*dt*Math.PI/5};}
